import unittest

from lead_router import Lead, route_lead


class RouterTests(unittest.TestCase):
    def test_existing_route_is_idempotent(self):
        lead = Lead("L-1", 50_000, "EU", existing_route="manual_review")
        self.assertEqual(route_lead(lead), "manual_review")

    def test_negative_amount_is_invalid(self):
        with self.assertRaises(ValueError):
            route_lead(Lead("L-2", -1, "EU"))

    def test_missing_region_goes_to_manual_review(self):
        for region in (None, "", "   "):
            with self.subTest(region=region):
                self.assertEqual(route_lead(Lead("L-3", 25_000, region)), "manual_review")

    def test_high_value_goes_to_senior(self):
        self.assertEqual(route_lead(Lead("L-4", 10_000, "EU")), "senior")

    def test_ordinary_lead_goes_to_standard(self):
        self.assertEqual(route_lead(Lead("L-5", 9_999, "EU")), "standard")


if __name__ == "__main__":
    unittest.main()

